import{_ as e,o as t,c as s,ak as o}from"./chunks/framework.DKi5cyCJ.js";const h=JSON.parse('{"title":"UART 串口","description":"8N1 帧格式、波特率误差、TXE 与 TC、DMA 加空闲中断、RS485","frontmatter":{"title":"UART 串口","description":"8N1 帧格式、波特率误差、TXE 与 TC、DMA 加空闲中断、RS485","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-UART串口.md","filePath":"pages/blog/2026-10-20-UART串口.md"}'),r={name:"pages/blog/2026-10-20-UART串口.md"};function l(i,a,p,n,d,c){return t(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="uart-帧格式、波特率与-rs485" tabindex="-1">UART：帧格式、波特率与 RS485 <a class="header-anchor" href="#uart-帧格式、波特率与-rs485" aria-label="Permalink to &quot;UART：帧格式、波特率与 RS485&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a> · <a href="/demos/uart-timing.html" target="_blank">时序动画</a></p></blockquote><div class="blog-demo-frame"><iframe src="/demos/uart-timing.html?embed=1" title="UART 时序动态演示" loading="lazy"></iframe></div><p>UART 没有时钟线。空闲为高。一帧是起始位低电平、数据位低位先发、可选校验、停止位高电平。MCU 引脚是 TTL 电平。RS-232 是负逻辑，中间要有电平转换。TX 接对方 RX，并且共地。</p><p><code>0x35</code> 的二进制是 <code>0011 0101</code>，线上数据位依次是 <code>1 0 1 0 1 1 0 0</code>，前面加起始 0，后面加停止 1。8N1 一共 10 位。115200 时整帧约 86.8 µs。示波器上宽度若是两倍，就是时钟或波特率差了一倍。</p><h2 id="波特率" tabindex="-1">波特率 <a class="header-anchor" href="#波特率" aria-label="Permalink to &quot;波特率&quot;">​</a></h2><p>过采样 16 时，波特率 = fck / (16 × USARTDIV)。84 MHz 对 115200：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>USARTDIV = 84e6 / (16 × 115200) = 45.5729</span></span>
<span class="line"><span>小数取 9/16，实际约 115226，误差约 0.02%</span></span></code></pre></div><p>误差超过大约 ±2% 时，后几位会采错。STM32 在 8 位数据再加校验时，字长要设成 9 位。</p><h2 id="txe-和-tc" tabindex="-1">TXE 和 TC <a class="header-anchor" href="#txe-和-tc" aria-label="Permalink to &quot;TXE 和 TC&quot;">​</a></h2><p>TXE 表示可以写下一位，移位寄存器里可能还有数据。TC 表示停止位已经发完。RS485 必须等 TC 再关闭发送使能，否则最后一帧被截断。接收时发送使能必须关掉。长线两端 120 Ω，空闲时用偏置电阻保证差分有确定极性。</p><p>不定长接收常用 DMA 循环写缓冲，加上空闲线中断。已收长度是缓冲总长减去 NDTR。循环模式下写指针会回绕。溢出标志不清除的话，后面的接收会停住，清除方法一般是读状态再读数据。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>`,13)])])}const m=e(r,[["render",l]]);export{h as __pageData,m as default};
